import fs from "node:fs";
import path from "node:path";
import type {
  CabinetLaminateCategory,
  CabinetLaminateCollection,
  CabinetLaminateGrain,
  CabinetLaminateTuple,
} from "../lib/cabinet-laminate-runtime-types";

// Writes lib/generated/cabinet-laminates.generated.ts from catalog/laminates/<supplier>/<collection>.json.
// --check fails when the generated file is out of date. The JSON catalogues are made from the
// masters by ~/Developer/material-masters/<supplier>/scripts/make_app_copies.py.

const CATALOG_ROOT = path.join(process.cwd(), "catalog", "laminates");
const GENERATED_PATH = path.join(process.cwd(), "lib", "generated", "cabinet-laminates.generated.ts");
const CATEGORIES: readonly CabinetLaminateCategory[] = ["abstracts", "metals", "pearlescents", "solids", "unicore", "woodgrains"];
const GRAINS: readonly CabinetLaminateGrain[] = ["along", "across", "pattern", "none"];

type CatalogEntry = {
  id: string;
  code: string;
  name: string;
  category: string;
  colour: string;
  render: string;
  grain: string;
  texture?: { url: string; swatch_url: string; width_mm: number; height_mm: number };
};
type CatalogFile = {
  schema_version: number;
  supplier: string;
  collection: string;
  collection_id: string;
  source: { url: string };
  sheet: { width_mm: number; height_mm: number; thickness_mm: number };
  entries: CatalogEntry[];
};

function fail(file: string, message: string): never {
  throw new Error(`${path.relative(process.cwd(), file)}: ${message}`);
}

function isCategory(value: string): value is CabinetLaminateCategory {
  return (CATEGORIES as readonly string[]).includes(value);
}

function isGrain(value: string): value is CabinetLaminateGrain {
  return (GRAINS as readonly string[]).includes(value);
}

function toTuple(file: string, entry: CatalogEntry): CabinetLaminateTuple {
  if (!isCategory(entry.category)) fail(file, `${entry.id} has an unknown category ${entry.category}`);
  if (!isGrain(entry.grain)) fail(file, `${entry.id} has an unknown grain ${entry.grain}`);
  if (!/^#[0-9a-f]{6}$/.test(entry.colour)) fail(file, `${entry.id} has a malformed colour`);
  const texture = entry.texture;
  if ((entry.render === "texture") !== Boolean(texture)) fail(file, `${entry.id} render and texture disagree`);
  if (texture && !(texture.width_mm > 0 && texture.height_mm > 0)) fail(file, `${entry.id} has no texture size`);
  return [
    entry.id,
    entry.code,
    entry.name,
    entry.category,
    entry.colour,
    texture?.url ?? null,
    texture?.swatch_url ?? null,
    texture?.width_mm ?? null,
    texture?.height_mm ?? null,
    entry.grain,
  ];
}

function readCollections(): CabinetLaminateCollection[] {
  const files = fs
    .readdirSync(CATALOG_ROOT, { withFileTypes: true })
    .filter((supplier) => supplier.isDirectory())
    .flatMap((supplier) =>
      fs
        .readdirSync(path.join(CATALOG_ROOT, supplier.name))
        .filter((name) => name.endsWith(".json"))
        .map((name) => path.join(CATALOG_ROOT, supplier.name, name))
    )
    .sort();
  const ids = new Set<string>();
  return files.map((file) => {
    const catalog = JSON.parse(fs.readFileSync(file, "utf8")) as CatalogFile;
    if (catalog.schema_version !== 1) fail(file, "schema_version must be 1");
    const laminates = catalog.entries.map((entry) => {
      if (ids.has(entry.id)) fail(file, `duplicate laminate id ${entry.id}`);
      ids.add(entry.id);
      return toTuple(file, entry);
    });
    return {
      id: catalog.collection_id,
      supplier: catalog.supplier,
      name: catalog.collection,
      sourceUrl: catalog.source.url,
      sheetMm: { width: catalog.sheet.width_mm, height: catalog.sheet.height_mm, thickness: catalog.sheet.thickness_mm },
      laminates,
    };
  });
}

export function buildCabinetLaminateRuntimeSource(): string {
  const collections = readCollections();
  const body = collections
    .map((collection) => {
      const { laminates, ...rest } = collection;
      const fields = JSON.stringify(rest).slice(1, -1);
      const rows = laminates.map((tuple) => `      ${JSON.stringify(tuple)},`).join("\n");
      return `  {\n    ${fields},\n    laminates: [\n${rows}\n    ],\n  },`;
    })
    .join("\n");
  return [
    "// This file is generated by scripts/generate-cabinet-laminate-runtime.ts.",
    "// Do not edit manually. Update catalog/laminates and rerun generation.",
    "",
    'import type { CabinetLaminateCollection } from "../cabinet-laminate-runtime-types";',
    "",
    "export const CABINET_LAMINATE_COLLECTIONS: readonly CabinetLaminateCollection[] = [",
    body,
    "];",
    "",
  ].join("\n");
}

function main(): void {
  const source = buildCabinetLaminateRuntimeSource();
  const current = fs.existsSync(GENERATED_PATH) ? fs.readFileSync(GENERATED_PATH, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (current !== source) {
      console.error("lib/generated/cabinet-laminates.generated.ts is out of date. Run npm run generate:cabinet-laminates.");
      process.exit(1);
    }
    console.log("Cabinet laminate runtime is current.");
    return;
  }
  fs.writeFileSync(GENERATED_PATH, source);
  console.log(`Wrote ${path.relative(process.cwd(), GENERATED_PATH)}.`);
}

if (require.main === module) main();
